<?php require_once __DIR__.'/../includes/bootstrap.php';$u=require_role('filmmaker');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$type=trim($_POST['project_type']??'');$city=trim($_POST['city']??'');$role=trim($_POST['role_description']??'');$desc=trim($_POST['description']??'');if(!$title||!$city||!$role||!$desc||!in_array($type,['Feature Film','Short Film','Web Series','Advertisement','Music Video','Other'],true))$error='Please complete all required fields.';else{$s=db()->prepare('INSERT INTO casting_calls(user_id,title,project_type,city,role_description,age_min,age_max,gender,deadline,description) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$u['id'],$title,$type,$city,$role,$_POST['age_min']!==''?(int)$_POST['age_min']:null,$_POST['age_max']!==''?(int)$_POST['age_max']:null,$_POST['gender']??'Any',$_POST['deadline']?:null,$desc]);header('Location: '.url('dashboard.php'));exit;}}$pageTitle='Create casting call';require __DIR__.'/../includes/header.php';?><main class="page-wrap"><div class="container"><div class="eyebrow dark">GIVE YOUR PROJECT ITS CAST</div><h1 class="page-title">Create a casting call.</h1><div class="form-card"><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>PROJECT TITLE *</label><input name="title" required maxlength="150"></div><div class="form-grid"><div class="field"><label>PROJECT TYPE *</label><select name="project_type"><?php foreach(['Feature Film','Short Film','Web Series','Advertisement','Music Video','Other'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>CITY *</label><input name="city" required placeholder="Bengaluru"></div><div class="field"><label>MINIMUM AGE</label><input type="number" name="age_min" min="16" max="100"></div><div class="field"><label>MAXIMUM AGE</label><input type="number" name="age_max" min="16" max="100"></div><div class="field"><label>GENDER</label><select name="gender"><option>Any</option><option>Female</option><option>Male</option><option>Non-binary</option></select></div><div class="field"><label>APPLICATION DEADLINE</label><input type="date" name="deadline" min="<?=date('Y-m-d')?>"></div></div><div class="field"><label>ROLE / CHARACTER *</label><input name="role_description" required placeholder="Lead actor, supporting role..."></div><div class="field"><label>PROJECT & AUDITION DETAILS *</label><textarea name="description" required></textarea></div><button class="btn btn-primary form-submit">Publish casting call ↗</button></form></div></div></main><?php require __DIR__.'/../includes/footer.php'; ?>